#!/usr/bin/env python3
"""
Round 104b tiles patch (28 September 2026), beside round104b_culprits.py.
It also carries round 101b's files (never uploaded) and round 103b's.

  scripts/giga_schools.py     new, daily: finds the address of Giga's own school
                              tiles and writes giga/schools_tiles.json.
  scripts/stock_exchanges.py  new, weekly: Wikipedia's list of major stock
                              exchanges, placed and valued (markets/).
  schools/culprits.geojson    new: who made schooling a machine for obedience,
                              sorting and selling (compiled, sourced).
  From 101b: scripts/mapspam.py, iuu_vessels.py, crime_probe.py,
             nusantara_health.py.
  From 103b: scripts/research_makers.py, fertility_policy.py, slavery_world.py,
             holidays/culprits.geojson, shapes/slavery_trackers.*.

Whole files, written only where they differ. Run from the repository root.
"""
import base64, pathlib

FILES = {'scripts/mapspam.py': '', 'scripts/iuu_vessels.py': '', 'scripts/crime_probe.py': '', 'scripts/nusantara_health.py': '', 'scripts/research_makers.py': '', 'scripts/fertility_policy.py': '', 'scripts/slavery_world.py': '', 'holidays/culprits.geojson': '', 'shapes/slavery_trackers.geojson': '', 'shapes/slavery_trackers.details.json': '', 'scripts/giga_schools.py': '', 'scripts/stock_exchanges.py': '', 'schools/culprits.geojson': ''}

changed = []
for path, b64 in FILES.items():
    p = pathlib.Path(path)
    new = base64.b64decode(b64)
    if not p.parent.exists() and p.parent.name not in ("holidays", "schools"):
        raise SystemExit(f"round104b: {p.parent} not found; run from the culprits-tiles-more root")
    if p.exists() and p.read_bytes() == new:
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(new)
    changed.append(path)
print("round104b: " + (", ".join(changed) if changed else "nothing to change (already applied)"))
